package ru.mytv.launcher;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.media.ExifInterface;
import android.os.*;
import android.view.Gravity;
import android.widget.*;
import java.io.ByteArrayInputStream;
import java.util.*;
import java.util.concurrent.*;
public class Scenes extends FrameLayout {
 final Handler ui=new Handler(Looper.getMainLooper());final Random random=new Random();final ImageView photo;final TextView clock,credit;final boolean onlyClock,overlay,labels;final int photoSeconds,moveSeconds,imageAlpha;volatile boolean running;volatile int generation;boolean showingPhoto;ExecutorService pool;int index;
 final String[] urls={"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1920&h=1080&q=80","https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1920&h=1080&q=80","https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1920&h=1080&q=80"};
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 public Scenes(Context c,boolean clocks){this(c,clocks,true);}
 public Scenes(Context c,boolean clocks,boolean respectMode){super(c);SharedPreferences p=SaverOptions.prefs(c);onlyClock=clocks||(respectMode&&p.getBoolean("clockMode",false));overlay=p.getBoolean("overlay",false);labels=p.getBoolean("captions",true);photoSeconds=Math.max(30,p.getInt("photo",60));moveSeconds=Math.max(5,p.getInt("move",15));int brightness=Math.max(10,Math.min(100,p.getInt("brightness",100)));imageAlpha=255*brightness/100;setBackgroundColor(Color.BLACK);photo=new ImageView(c);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);addView(photo,new LayoutParams(-1,-1));clock=new TextView(c);clock.setTextSize(Math.max(24,Math.min(96,p.getInt("size",56))));int shade=204*brightness/100;clock.setTextColor(Color.rgb(shade,shade,shade));clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));addView(clock,new LayoutParams(-2,-2));credit=new TextView(c);credit.setTextSize(15);int white=255*brightness/100;credit.setTextColor(Color.rgb(white,white,white));credit.setMaxLines(3);credit.setEllipsize(android.text.TextUtils.TruncateAt.END);credit.setPadding(dp(14),dp(8),dp(14),dp(8));GradientDrawable bg=new GradientDrawable();bg.setColor(0x99090d18);bg.setCornerRadius(dp(10));credit.setBackground(bg);LayoutParams cp=new LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.LEFT);cp.setMargins(dp(24),0,dp(24),dp(24));addView(credit,cp);credit.setVisibility(GONE);index=random.nextInt(urls.length);}
 final Runnable time=new Runnable(){public void run(){if(!running)return;clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));clock.setVisibility(!showingPhoto||overlay?VISIBLE:INVISIBLE);clock.setAlpha(1f);ui.postDelayed(this,1000);}};
 final Runnable move=new Runnable(){public void run(){if(!running)return;if(getWidth()==0||getHeight()==0||clock.getWidth()==0||clock.getHeight()==0){ui.postDelayed(this,100);return;}int pad=dp(24),maxX=Math.max(0,getWidth()-clock.getWidth()),maxY=Math.max(0,getHeight()-clock.getHeight()-(labels&&!onlyClock?dp(128):0));int minX=Math.min(pad,maxX),minY=Math.min(pad,maxY);int spanX=Math.max(0,maxX-2*pad),spanY=Math.max(0,maxY-2*pad);clock.animate().cancel();clock.animate().x(minX+random.nextInt(spanX+1)).y(minY+random.nextInt(spanY+1)).setDuration(1200).start();ui.postDelayed(this,moveSeconds*1000L);}};
 final Runnable next=new Runnable(){public void run(){if(!running)return;load();ui.postDelayed(this,photoSeconds*1000L);}};
 void start(){if(running)return;generation++;running=true;showingPhoto=false;credit.setVisibility(GONE);clock.setVisibility(VISIBLE);clock.setAlpha(1f);pool=Executors.newSingleThreadExecutor();ui.post(time);ui.post(move);if(!onlyClock)ui.post(next);}
 void stop(){running=false;generation++;ui.removeCallbacksAndMessages(null);if(pool!=null)pool.shutdownNow();photo.animate().cancel();clock.animate().cancel();photo.setImageDrawable(null);credit.setVisibility(GONE);}
 static String clean(String s){if(s==null)return "";s=s.replaceAll("[\\p{Cntrl}\\s]+"," ").trim();return s.length()>160?s.substring(0,160):s;}
 static String description(byte[] bytes){String title="",author="";try{ExifInterface exif=new ExifInterface(new ByteArrayInputStream(bytes));title=clean(exif.getAttribute("ImageDescription"));author=clean(exif.getAttribute("Artist"));if(title.toUpperCase(Locale.ROOT).contains("DIGITAL CAMERA"))title="";}catch(Exception ignored){}return (title.isEmpty()?"":title+"\n")+"Источник: Unsplash"+(author.isEmpty()?"":" · "+author);}
 void load(){final int token=generation;final String url=urls[index++%urls.length];pool.submit(()->{Bitmap result=null;String caption="Источник: Unsplash";try{byte[] bytes=Updates.fetch(url,8388608);if(labels)caption=description(bytes);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1)throw new Exception("Invalid image");o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1920||o.outHeight/o.inSampleSize>1080)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;result=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);}catch(Exception e){android.util.Log.w("MyTV","Landscape unavailable",e);}final Bitmap bitmap=result;final String text=caption;ui.post(()->{if(!running||token!=generation){if(bitmap!=null)bitmap.recycle();return;}photo.animate().cancel();credit.setVisibility(GONE);if(bitmap==null){showingPhoto=false;photo.setImageDrawable(null);clock.setVisibility(VISIBLE);}else{photo.setImageBitmap(bitmap);photo.setImageAlpha(imageAlpha);photo.setAlpha(0f);credit.setText(text);photo.animate().alpha(1f).setDuration(1200).withEndAction(()->{if(running&&token==generation){showingPhoto=true;clock.setVisibility(overlay?VISIBLE:INVISIBLE);credit.setVisibility(labels?VISIBLE:GONE);}}).start();}});});}
}
